import{_ as i,o as s,c as o,ag as t}from"./chunks/framework.B7PviQjB.js";const a="/docs/images/developers/self-hosting/sign-in-providers.png",u=JSON.parse('{"title":"Sign-in providers","description":"Configure GitHub, GitHub Enterprise, and Google sign-in for a self-hosted Wafflebase, and make cookies, CLI sign-in, and desktop app sign-in work over HTTPS.","frontmatter":{"title":"Sign-in providers","description":"Configure GitHub, GitHub Enterprise, and Google sign-in for a self-hosted Wafflebase, and make cookies, CLI sign-in, and desktop app sign-in work over HTTPS.","type":"how-to"},"headers":[],"relativePath":"developers/self-hosting/sign-in.md","filePath":"developers/self-hosting/sign-in.md"}'),n={name:"developers/self-hosting/sign-in.md"};function l(r,e,p,c,d,h){return s(),o("div",null,[...e[0]||(e[0]=[t(`<h1 id="sign-in-providers" tabindex="-1">Sign-in providers <a class="header-anchor" href="#sign-in-providers" aria-label="Permalink to &quot;Sign-in providers&quot;">​</a></h1><p>Configure who can sign in to your Wafflebase instance: GitHub (required), GitHub Enterprise Server, and Google (optional).</p><p>People sign in with an email address their provider has verified. The first sign-in creates the account and its first workspace. The same email reaches the same account through either provider.</p><div class="info custom-block"><p class="custom-block-title">Before you start</p><ul><li>You need the backend&#39;s public URL, for example <code>https://api.example.com</code>. Locally it is <code>http://localhost:3000</code>.</li><li>Changes take effect when you restart the backend.</li></ul></div><h2 id="set-up-github-sign-in" tabindex="-1">Set up GitHub sign-in <a class="header-anchor" href="#set-up-github-sign-in" aria-label="Permalink to &quot;Set up GitHub sign-in&quot;">​</a></h2><ol><li><p>Open <a href="https://github.com/settings/developers" target="_blank" rel="noreferrer">GitHub Developer Settings</a> and click <strong>New OAuth App</strong>.</p></li><li><p>Set <strong>Homepage URL</strong> to your frontend URL, for example <code>https://app.example.com</code>.</p></li><li><p>Set <strong>Authorization callback URL</strong> to <code>https://api.example.com/auth/github/callback</code>.</p></li><li><p>Register the app, then generate a client secret.</p></li><li><p>Add the values to the backend configuration:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GITHUB_CLIENT_ID=your_client_id</span></span>
<span class="line"><span>GITHUB_CLIENT_SECRET=your_client_secret</span></span>
<span class="line"><span>GITHUB_CALLBACK_URL=https://api.example.com/auth/github/callback</span></span>
<span class="line"><span>FRONTEND_URL=https://app.example.com</span></span></code></pre></div></li><li><p>Restart the backend.</p></li></ol><p>The sign-in page shows <strong>Continue with GitHub</strong>. Use a separate OAuth app for local development, with the callback <code>http://localhost:3000/auth/github/callback</code>.</p><h2 id="use-github-enterprise" tabindex="-1">Use GitHub Enterprise <a class="header-anchor" href="#use-github-enterprise" aria-label="Permalink to &quot;Use GitHub Enterprise&quot;">​</a></h2><ol><li><p>Create the OAuth app on your GitHub Enterprise Server instance, with the same callback URL as above.</p></li><li><p>Set the client ID, secret, and callback URL as for github.com.</p></li><li><p>Point all four endpoints at your instance:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GITHUB_AUTHORIZATION_URL=https://ghe.example.com/login/oauth/authorize</span></span>
<span class="line"><span>GITHUB_TOKEN_URL=https://ghe.example.com/login/oauth/access_token</span></span>
<span class="line"><span>GITHUB_USER_PROFILE_URL=https://ghe.example.com/api/v3/user</span></span>
<span class="line"><span>GITHUB_USER_EMAIL_URL=https://ghe.example.com/api/v3/user/emails</span></span></code></pre></div></li><li><p>Restart the backend.</p></li></ol><p>Set all four. If <code>GITHUB_USER_EMAIL_URL</code> is missing, sign-in fails with <code>Bad credentials</code>; see <a href="/docs/developers/self-hosting/troubleshooting.html#github-enterprise-sign-in-fails-with-bad-credentials">troubleshooting</a>.</p><h2 id="set-up-google-sign-in" tabindex="-1">Set up Google sign-in <a class="header-anchor" href="#set-up-google-sign-in" aria-label="Permalink to &quot;Set up Google sign-in&quot;">​</a></h2><ol><li><p>In the Google Cloud console, create an OAuth client ID of type <strong>Web application</strong>.</p></li><li><p>Add <code>https://api.example.com/auth/google/callback</code> as an authorized redirect URI.</p></li><li><p>Add the three values to the backend configuration:</p><div class="language-env vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">env</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GOOGLE_CLIENT_ID=your_client_id.apps.googleusercontent.com</span></span>
<span class="line"><span>GOOGLE_CLIENT_SECRET=your_client_secret</span></span>
<span class="line"><span>GOOGLE_CALLBACK_URL=https://api.example.com/auth/google/callback</span></span></code></pre></div></li><li><p>Restart the backend.</p></li></ol><p>The sign-in page shows <strong>Continue with Google</strong> below the GitHub button. All three variables are required. With one missing, the button does not appear and the backend logs <code>Google sign-in is disabled:</code> followed by the missing names.</p><p><img src="`+a+'" alt="Sign-in page with Continue with GitHub and Continue with Google buttons"></p><h2 id="serve-sign-in-over-https" tabindex="-1">Serve sign-in over HTTPS <a class="header-anchor" href="#serve-sign-in-over-https" aria-label="Permalink to &quot;Serve sign-in over HTTPS&quot;">​</a></h2><p>The backend decides whether its cookies are <code>Secure</code> (and use the <code>__Host-</code> prefix) in this order:</p><ol><li><code>COOKIE_SECURE</code>: <code>true</code>/<code>1</code> means secure, <code>false</code>/<code>0</code> means not secure.</li><li>The scheme of <code>GITHUB_CALLBACK_URL</code>: <code>https://</code> means secure.</li><li>With no callback URL set: secure when <code>NODE_ENV=production</code>.</li></ol><p>To get this right:</p><ol><li>Set <code>GITHUB_CALLBACK_URL</code> to the <code>https://</code> URL your users reach, even when TLS ends at a proxy.</li><li>If you cannot, set <code>COOKIE_SECURE=true</code>.</li></ol><p><code>GOOGLE_CALLBACK_URL</code> does not affect this. An HTTPS deployment that leaves <code>GITHUB_CALLBACK_URL</code> unset and uses only Google should set <code>COOKIE_SECURE=true</code>. With <code>NODE_ENV=production</code> and a non-loopback <code>http://</code> callback URL, the backend logs a warning at the first sign-in that cookies are issued without <code>Secure</code>.</p><h2 id="allow-cli-sign-in" tabindex="-1">Allow CLI sign-in <a class="header-anchor" href="#allow-cli-sign-in" aria-label="Permalink to &quot;Allow CLI sign-in&quot;">​</a></h2><p><code>wafflebase login</code> signs in through the browser with GitHub. Point the CLI at your backend:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">wafflebase</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --server</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://api.example.com</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> login</span></span></code></pre></div><p>The backend allows CLI sign-in only when its cookies are <code>Secure</code> (an <code>https://</code> callback URL or <code>COOKIE_SECURE=true</code>) or the callback URL is loopback (<code>localhost</code>, <code>127.0.0.1</code>, <code>[::1]</code>, or a <code>*.localhost</code> name). Otherwise the backend answers <code>400 Command-line sign-in requires an https server</code>. Browser sign-in and API keys (<code>--api-key</code>) work either way; see <a href="/docs/developers/cli/">CLI</a>.</p><h2 id="allow-desktop-app-sign-in" tabindex="-1">Allow desktop app sign-in <a class="header-anchor" href="#allow-desktop-app-sign-in" aria-label="Permalink to &quot;Allow desktop app sign-in&quot;">​</a></h2><p>The <a href="/docs/start/desktop.html">desktop app</a> signs in through the system browser with GitHub, like the CLI. It needs:</p><ol><li>A Wafflebase server recent enough to offer desktop sign-in. An older server makes the app show <code>This server is too old for desktop sign-in</code>.</li><li>The same conditions as CLI sign-in above. Otherwise the app shows <code>This server has desktop sign-in turned off</code>.</li><li>A backend origin (<code>VITE_BACKEND_API_URL</code>) on <code>https://</code>, or on <code>http://</code> only at a loopback address. The app won&#39;t sign in against a plain <code>http://</code> backend elsewhere.</li><li>Users who enter <code>FRONTEND_URL</code> as the server address in the app. The backend redirects there after sign-in, so an alias or a <code>www.</code> variant ends the sign-in in the browser instead of the app.</li></ol><p>The Windows app finishes sign-in from the origin <code>http://tauri.localhost</code>. To refuse it, set <code>WAFFLEBASE_DESKTOP_WINDOWS_ORIGIN=false</code>. The Windows app then shows that the server doesn&#39;t accept its sign-in; the Mac app is unaffected.</p><h2 id="known-limitations" tabindex="-1">Known limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known limitations&quot;">​</a></h2><ul><li>Turning <code>Secure</code> on renames the session cookies, so everyone signed in is signed out once.</li><li>Google sign-in is browser-only. The CLI signs in with GitHub or an API key, and the desktop app with GitHub.</li><li>An account created before email verification was required can be reached only through its original provider until its owner signs in with that provider once. Until then, the other provider shows &quot;An account already exists for that email address under the other sign-in provider.&quot;</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/docs/developers/self-hosting/configuration.html#backend-sessions-and-cookies">Configuration</a> for token and cookie lifetimes.</li><li><a href="/docs/developers/self-hosting/deploy.html#run-behind-a-tls-proxy">Deploy to production</a> for the rest of the proxy setup.</li><li><a href="/docs/developers/self-hosting/troubleshooting.html">Troubleshooting</a> for sign-in errors.</li></ul>',32)])])}const b=i(n,[["render",l]]);export{u as __pageData,b as default};
